import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"39、【蹇】 艮下坎上","description":"橫渠易說 - 39、【蹇】 艮下坎上","frontmatter":{"title":"39、【蹇】 艮下坎上","description":"橫渠易說 - 39、【蹇】 艮下坎上"},"headers":[],"relativePath":"classics/hengqu/041.md","filePath":"classics/hengqu/041.md"}'),l={name:"classics/hengqu/041.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_39、【蹇】-艮下坎上" tabindex="-1">39、【蹇】 艮下坎上 <a class="header-anchor" href="#_39、【蹇】-艮下坎上" aria-label="Permalink to “39、【蹇】 艮下坎上”">​</a></h1><p>蹇之世，大人乃能成功。</p><h3 id="彖曰-蹇-難也-險在前也。見險而能止-知矣哉-蹇利西南-往得中也-不利東北-其道窮也-利見大人-往有功也-當位-貞吉-以正邦也。蹇之時用大矣哉" tabindex="-1">彖曰：蹇，難也，險在前也。見險而能止，知矣哉!“蹇利西南”，往得中也，“不利東北”，其道窮也，“利見大人”，往有功也，當位“貞吉”，以正邦也。蹇之時用大矣哉! <a class="header-anchor" href="#彖曰-蹇-難也-險在前也。見險而能止-知矣哉-蹇利西南-往得中也-不利東北-其道窮也-利見大人-往有功也-當位-貞吉-以正邦也。蹇之時用大矣哉" aria-label="Permalink to “彖曰：蹇，難也，險在前也。見險而能止，知矣哉!“蹇利西南”，往得中也，“不利東北”，其道窮也，“利見大人”，往有功也，當位“貞吉”，以正邦也。蹇之時用大矣哉!”">​</a></h3><h3 id="象曰-山上有水-蹇-君子以反身修德。" tabindex="-1">象曰：山上有水，蹇，君子以反身修德。 <a class="header-anchor" href="#象曰-山上有水-蹇-君子以反身修德。" aria-label="Permalink to “象曰：山上有水，蹇，君子以反身修德。”">​</a></h3><p>見險能止，然不可終止而已，當見大人之德，進之坤順致養之地，則得其中。若更退守艮止，則難無時而解也，故曰“不利東北，其道窮也”。至於解卦，則曰“其來複吉，乃得中也”，與此互見矣，蓋難在內外，與震艮之動止則相反爾。</p><h3 id="初六-往蹇來譽。-象曰-往蹇來譽-宜待也。" tabindex="-1">初六，往蹇來譽。 象曰：“往蹇來譽”，宜待也。 <a class="header-anchor" href="#初六-往蹇來譽。-象曰-往蹇來譽-宜待也。" aria-label="Permalink to “初六，往蹇來譽。 象曰：“往蹇來譽”，宜待也。”">​</a></h3><p>蹇難之際，用心存公，無所偏系，故譽美可獲。</p><h3 id="六二-王臣蹇蹇-匪躬之故。-象曰-王臣蹇蹇-終無尤也。" tabindex="-1">六二，王臣蹇蹇，匪躬之故。 象曰：“王臣蹇蹇”，終無尤也。 <a class="header-anchor" href="#六二-王臣蹇蹇-匪躬之故。-象曰-王臣蹇蹇-終無尤也。" aria-label="Permalink to “六二，王臣蹇蹇，匪躬之故。 象曰：“王臣蹇蹇”，終無尤也。”">​</a></h3><h3 id="九三-往蹇來反。-象曰-往蹇來反-內喜之也。" tabindex="-1">九三，往蹇來反。 象曰：“往蹇來反”，內喜之也。 <a class="header-anchor" href="#九三-往蹇來反。-象曰-往蹇來反-內喜之也。" aria-label="Permalink to “九三，往蹇來反。 象曰：“往蹇來反”，內喜之也。”">​</a></h3><h3 id="六四-往蹇來連。-象曰-往蹇來連-當位實也。" tabindex="-1">六四，往蹇來連。 象曰：“往蹇來連”，當位實也。 <a class="header-anchor" href="#六四-往蹇來連。-象曰-往蹇來連-當位實也。" aria-label="Permalink to “六四，往蹇來連。 象曰：“往蹇來連”，當位實也。”">​</a></h3><p>連，順也，序也。蹇反當位正吉，六四未能出險，故可止，而順序以俟難之解，當位處陰之實。</p><h3 id="九五-大蹇朋來。-象曰-大蹇朋來-以中節也。" tabindex="-1">九五，大蹇朋來。 象曰：“大蹇朋來”，以中節也。 <a class="header-anchor" href="#九五-大蹇朋來。-象曰-大蹇朋來-以中節也。" aria-label="Permalink to “九五，大蹇朋來。 象曰：“大蹇朋來”，以中節也。”">​</a></h3><p>剛中之德，為物所歸。</p><h3 id="上六-往蹇來碩-吉-利見大人。-象曰-往蹇來碩-志在內也。利見大人-以從貴也。" tabindex="-1">上六，往蹇來碩，吉，利見大人。 象曰：“往蹇來碩”，志在內也。利見大人，以從貴也。 <a class="header-anchor" href="#上六-往蹇來碩-吉-利見大人。-象曰-往蹇來碩-志在內也。利見大人-以從貴也。" aria-label="Permalink to “上六，往蹇來碩，吉，利見大人。 象曰：“往蹇來碩”，志在內也。利見大人，以從貴也。”">​</a></h3><p>與解繇同義。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
